import {sectors,states,stages,weights,labels,leadStatuses} from './intelligence-model.mjs';
export function createIntelligence({state,api,esc:e,toast,modal,render}){
 let data=null,detail=null,search='',sector='',region='',stage='',minimum='',windowFilter='',developer='';
 const routes=['intelligence','intelligence-projects','intelligence-leads','intelligence-reports','intelligence-admin'];
 const options=(values,current='')=>values.map(v=>`<option value="${e(v)}" ${v===current?'selected':''}>${e(sectors[v]||v)}</option>`).join('');
 const button=(label,action,id='',secondary=true)=>`<button class="${secondary?'secondary':''}" data-mi="${action}" data-id="${e(id)}">${e(label)}</button>`;
 const heading=(name,sub)=>`<div class="page-heading"><div><p class="eyebrow">PHILLIP RILEY / INTELLIGENCE</p><h1>${e(name)}</h1><p>${e(sub)}</p></div>${button('Refresh','refresh')}</div>`;
 const links=()=>`<div class="mi-tabs" aria-label="Intelligence sections">${routes.filter(r=>r!=='intelligence-admin'||state.me?.role==='admin').map((r,i)=>`<a class="${state.route===r?'selected':''}" href="#${r}">${['Overview','Projects','Client leads','Reports','Administration'][i]}</a>`).join('')}</div>`;
 const field=(label,name,value='',type='text')=>`<label>${e(label)}<input name="${name}" type="${type}" value="${e(value)}" maxlength="2000"></label>`;
 const pill=text=>`<span class="pill">${e(text)}</span>`;
 const filtered=()=>data.projects.filter(p=>{const q=p.payload;return (!search||JSON.stringify([q.name,q.developer,q.region]).toLowerCase().includes(search.toLowerCase()))&&(!sector||q.sectors.includes(sector))&&(!region||q.state===region)&&(!stage||q.stage===stage)&&(!minimum||q.investmentAud!==null&&q.investmentAud>=Number(minimum))&&(!developer||q.developer.toLowerCase().includes(developer.toLowerCase()))&&(!windowFilter||q.hiringWindow.toLowerCase().includes(windowFilter.toLowerCase()));});
 async function load(){if(state.me){data=await api('/intelligence');if(['admin','reviewer'].includes(state.me.role))data.duplicates=(await api('/intelligence/duplicates')).reviews;}else data=null;}
 function projectRows(){return filtered().map(p=>`<tr><td>${button(p.name,'project',p.id)}<small>${e(p.payload.region||'Region unknown')}</small></td><td>${e(p.state)}</td><td>${e(p.payload.sectors.map(s=>sectors[s]).join(', '))}</td><td>${e(p.stage)}<small>Evidence review required</small></td><td>${e(p.payload.developer||'Unknown')}</td><td>${e(p.payload.hiringWindow||'Unknown')}<small>Forecast</small></td></tr>`).join('');}
 function overview(){const latest=data.jobs[0];return `<div class="mi-hero"><div><p class="eyebrow">FROM PUBLIC EVIDENCE TO USEFUL CONVERSATIONS</p><h2>Find the right company.<br>Know why it matters.</h2><p>Track project progress, identify the likely hiring employer and give consultants a source-backed reason to call.</p><a class="button" href="#intelligence-projects">Explore projects →</a></div><div class="mi-hero-status"><span class="pill">${data.researchEnabled?'Research enabled':'Research paused'}</span><p>${data.scheduleEnabled?'Sydney schedules enabled':'Schedules awaiting activation'}</p><small>Email: ${e(data.emailMode)} · Every report needs approval</small></div></div><div class="mi-stats">${[['Tracked projects',data.projects.length],['Client opportunities',data.leads.length],['High priority',data.leads.filter(l=>l.score>=80).length],['Needs attention',data.alerts.length]].map(([label,n])=>`<article><span>${label}</span><strong>${n}</strong></article>`).join('')}</div><div class="two-col"><section class="panel"><h2>Start with evidence</h2><ol><li>Add a public project announcement with its exact supporting excerpt.</li><li>Review facts and announced plans separately from hiring forecasts.</li><li>Score the employing organisation, assign an owner and agree a next step.</li><li>Review the weekly report before approving distribution.</li></ol><p>No candidate records or private CRM information are needed.</p></section><section class="panel"><h2>Research & spending</h2><p>Last job: ${latest?e(latest.kind+' · '+latest.status):'No research runs yet'}</p><p>Next weekly distribution window: Monday 08:00 Australia/Sydney, subject to approval and completed research.</p><p>Estimated API use this month: <strong>US$${data.budget.spent.toFixed(2)}</strong><br>Reserved for outstanding requests: US$${data.budget.reserved.toFixed(2)}</p><small>Estimates are separate from provider invoices. Paused research does not prevent manual evidence review.</small></section></div>${alerts()}`;}
 function alerts(){return data.alerts.length?`<section class="panel"><h2>Needs attention</h2>${data.alerts.map(a=>`<p>${pill(a.severity)} ${e(a.message)}</p>`).join('')}</section>`:'';}
 function projects(){return `<section class="panel"><div class="panel-head"><h2>Project explorer</h2>${['admin','reviewer'].includes(state.me.role)?button('Add public evidence','add-project'):''}</div><form id="mi-filters" class="form-grid">${field('Search projects','search',search)}<label>Sector<select name="sector"><option value="">All sectors</option>${options(Object.keys(sectors),sector)}</select></label><label>State / territory<select name="region"><option value="">All Australia</option>${options(states,region)}</select></label><label>Stage<select name="stage"><option value="">All stages</option>${options(stages,stage)}</select></label>${field('Developer contains','developer',developer)}${field('Minimum investment (AUD)','minimum',minimum,'number')}${field('Recruitment window contains','windowFilter',windowFilter)}<div class="actions"><button>Apply filters</button>${button('Clear','clear-filters')}</div></form><p>${filtered().length} projects · Unknown investment and timing remain unknown.</p><div class="table-wrap"><table><thead><tr><th>Project</th><th>State</th><th>Sector</th><th>Stage</th><th>Developer</th><th>Hiring window</th></tr></thead><tbody>${projectRows()||'<tr><td colspan="6">No projects match. Add public evidence to start the register.</td></tr>'}</tbody></table></div></section>`;}
 function leads(){return `<section class="panel"><h2>Company opportunities</h2><p>Scores rank business-development opportunities, not candidates. A large project alone can earn only 15 of 100 points.</p><div class="table-wrap"><table><thead><tr><th>Company / project</th><th>Priority</th><th>Status</th><th>Owner</th><th>Follow-up</th><th>Action</th></tr></thead><tbody>${data.leads.map(l=>`<tr><td><strong>${e(l.organisation)}</strong><small>${e(l.project)}</small></td><td>${l.score}/100<small>${l.score>=80?'High priority':l.score>=60?'Medium priority':'Monitor'}</small></td><td>${pill(l.status)}</td><td>${e(data.users.find(u=>u.id===l.owner_id)?.name||'Unassigned')}</td><td>${e(l.follow_up||'Not set')}</td><td>${button('Review & score','lead',l.id)}</td></tr>`).join('')||'<tr><td colspan="6">No company leads yet. Link an organisation to a project with supporting evidence.</td></tr>'}</tbody></table></div></section>`;}
 function reports(){return `<section class="panel"><div class="panel-head"><h2>Weekly report archive</h2>${['admin','reviewer'].includes(state.me.role)?button('Prepare report','report-form'):''}</div><p>Drafts remain visibly marked. Evidence checks and administrator approval are required before email distribution.</p>${data.reports.map(r=>{const v=JSON.parse(r.validation);return `<article class="mi-report"><div><h3>${e(r.period_start.slice(0,10))} — ${e(r.period_end.slice(0,10))}</h3>${pill(r.status)} ${pill(v.valid?'Checks passed':'Review required')}</div><div class="actions"><a href="/api/intelligence/reports/${r.id}/html">Download HTML</a><a href="/api/intelligence/reports/${r.id}/pdf">Download PDF</a>${['admin','reviewer'].includes(state.me.role)?button('Refresh checks','validate-report',r.id):''}${state.me.role==='admin'&&r.status==='draft'&&v.valid?button('Approve report','approve-report',r.id):''}</div>${v.problems.length?`<details><summary>${v.problems.length} issues to resolve</summary><ul>${v.problems.map(p=>`<li>${e(p)}</li>`).join('')}</ul></details>`:''}</article>`;}).join('')||'<p>No reports prepared yet.</p>'}</section>`;}
 function admin(){if(state.me.role!=='admin')return '<section class="panel"><h2>Administrator access required</h2></section>';const c=data.config;return `<section class="panel"><h2>Activation & budget</h2><p>Server-side approval switches protect spending, schedules and email. Saving settings cannot bypass those switches.</p><form id="mi-settings"><div class="form-grid"><label>Research<select name="enabled"><option value="false" ${!c.enabled?'selected':''}>Paused</option><option value="true" ${c.enabled?'selected':''}>Enabled after approval</option></select></label><label>Email mode<select name="emailMode">${options(['off','test','production'],c.emailMode)}</select></label>${['monthlyCap','monthlyTarget','warningAt','criticalAt','shortlist','concurrency'].map(k=>field(({monthlyCap:'Monthly hard cap (USD, maximum 250)',monthlyTarget:'Monthly target (USD)',warningAt:'First alert (USD)',criticalAt:'Critical alert (USD)',shortlist:'Weekly shortlist (10–20)',concurrency:'Concurrent investigations (1–2)'})[k],k,c[k],'number')).join('')}</div><h3>Model routing</h3>${Object.entries(c.routes).map(([key,r])=>`<fieldset><legend>${e(key)}</legend><div class="form-grid"><label>Model<select name="${key}-model">${options(['gpt-6-luna','gpt-6.1-sol','gpt-6-astra'],r.model)}</select></label><label>Reasoning<select name="${key}-effort">${options(['low','medium','high','xhigh'],r.effort)}</select></label>${field('Maximum output tokens',key+'-maxOutput',r.maxOutput,'number')}${field('Maximum searches',key+'-maxSearches',r.maxSearches,'number')}</div></fieldset>`).join('')}<label>Approved public source domains (one per line)<textarea name="sourceDomains" rows="8">${e(c.sourceDomains.join('\n'))}</textarea></label><button>Save configuration</button><p class="error" role="alert"></p></form></section><section class="panel"><h2>Job operations</h2><div class="actions">${button('Queue discovery across eight sectors','discovery')}${button('Process pending jobs','tick')}${button('Check source links','check-sources')}</div><p>Processing a research job can use the API only when spending is enabled. An uncertain submission is held for reconciliation, never automatically sent again.</p><div class="table-wrap"><table><thead><tr><th>Job</th><th>Status</th><th>Model</th><th>Issue</th></tr></thead><tbody>${data.jobs.map(j=>`<tr><td>${e(j.kind)}</td><td>${e(j.status)}</td><td>${e(j.model_id||'No AI')}</td><td>${e(j.error||'—')}${['held','failed'].includes(j.status)?button('Retry after review','retry-job',j.id):j.status==='uncertain'?button('Reconcile response','reconcile-job',j.id):''}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Email subscriptions</h2><p>Test mode sends only to the separately approved test-recipient list. A configured company mail service is required.</p><form id="mi-subscription"><div class="form-grid">${field('Work email','email','','email')}<label>Subscription<select name="active"><option value="true">Active</option><option value="false">Unsubscribed</option></select></label><label>Recipient type<select name="testOnly"><option value="true">Test only</option><option value="false">Production recipient</option></select></label></div><button>Save subscription</button><p class="error" role="alert"></p></form>${data.subscriptions.map(s=>`<p>${e(s.email)} · ${s.active?'Active':'Unsubscribed'} · ${s.test_only?'Test':'Production'}</p>`).join('')}</section>${alerts()}<section class="panel"><h2>Possible duplicates</h2>${(data.duplicates||[]).map(r=>`<article><strong>${e(r.payload.name)}</strong><form class="form-grid" id="mi-duplicate-${r.id}" data-id="${r.id}"><label>Existing project<select name="targetId">${JSON.parse(r.candidates).map(id=>`<option value="${id}">${e(data.projects.find(p=>p.id===id)?.name||id)}</option>`).join('')}</select></label><label>Decision<select name="decision"><option value="merge">Link this evidence to the existing project</option><option value="dismiss">Dismiss this import</option></select></label><button>Resolve duplicate</button><p class="error" role="alert"></p></form></article>`).join('')||'<p>No ambiguous matches.</p>'}</section><section class="panel"><h2>Audit trail</h2>${data.audit.map(a=>`<p>${e(a.created_at)} · ${e(a.action)} · ${e(a.actor_id)}</p>`).join('')||'<p>No administrative changes yet.</p>'}</section>`;}
 function view(route){if(!state.me)return heading('Market Intelligence & Client Leads','Project evidence, company opportunities and weekly business-development reports.')+`<section class="panel"><h2>Sign in to access company intelligence</h2><p>Project records, lead assignments and reports are available only to approved staff. Your existing trials remain available from the workspace menu.</p><a href="/signin-with-chatgpt">Sign in with work email</a></section>`;if(!data)return '<section class="panel"><p>Intelligence data has not loaded. Use Refresh to try again.</p></section>';return heading('Market Intelligence & Client Leads','Public evidence. Clear priorities. Better-informed client conversations.')+links()+({intelligence:overview,'intelligence-projects':projects,'intelligence-leads':leads,'intelligence-reports':reports,'intelligence-admin':admin}[route])();}
 async function showProject(id){detail=await api('/intelligence/projects/'+id);const p=detail.payload;modal(`<h2>${e(p.name)}</h2><p>${e(p.state)} · ${e(p.region)} · ${e(p.stage)}</p><p>${e(p.description)}</p><p>Investment: ${p.investmentAud===null?'Unknown':'AUD '+p.investmentAud.toLocaleString()} · Capacity: ${e(p.capacity||'Unknown')}</p><p><strong>Recruitment forecast:</strong> ${e(p.hiringWindow||'Unknown')} · ${e(p.roles.join(', ')||'Roles not established')}</p><p><strong>Uncertainty:</strong> ${e(p.uncertainty||'Not assessed')}</p><h3>Organisations & responsibilities</h3>${detail.organisations.map(o=>`<p>${e(o.name)} · ${e(o.relationship_type)}</p>`).join('')}<h3>Claim-by-claim evidence</h3>${detail.claims.map(c=>`<section class="panel">${pill(c.kind)} ${pill(c.confidence)}<p>${e(c.statement)}</p>${c.sources.map(s=>`<p><a href="${e(s.source_url)}" target="_blank" rel="noreferrer">${e(s.title)}</a><br><small>${e(s.publisher)} · ${e(s.publication_date||'Date unknown')}</small><blockquote>${e(s.excerpt)}</blockquote></p>`).join('')}${['admin','reviewer'].includes(state.me.role)?button('Record evidence review','claim',c.id):''}</section>`).join('')}<h3>Event history</h3>${detail.events.map(x=>`<p>${e(x.event_date)} · ${e(x.event_type)}</p>`).join('')}<div class="actions">${['admin','reviewer'].includes(state.me.role)?button('Request verification','verification',id)+button('Request deep research','deep',id):''}</div>`);}
 async function showLead(id){const l=data.leads.find(l=>l.id===id),p=await api('/intelligence/projects/'+l.project_id),claims=p.claims.filter(c=>c.confidence!=='Unverified');modal(`<h2>${e(l.organisation)}</h2><p>${e(l.project)} · ${e(l.stage)}</p><p>Each non-zero score needs a reason and reviewed evidence. Check which organisation will hire and whether it may use external recruitment.</p><form id="mi-lead" data-id="${id}" data-version="${l.version}"><div class="form-grid"><label>Status<select name="status">${options(leadStatuses,l.status)}</select></label><label>Owner<select name="ownerId"><option value="">Unassigned</option>${data.users.map(u=>`<option value="${e(u.id)}" ${u.id===l.owner_id?'selected':''}>${e(u.name)}</option>`).join('')}</select></label>${field('Follow-up date','followUp',l.follow_up||'','date')}${field('Next action','action',l.payload.action)}${field('Dismissal reason (required if dismissed)','dismissalReason',l.payload.dismissalReason)}</div><label>Internal notes<textarea name="notes" maxlength="4000">${e(l.payload.notes)}</textarea></label><h3>Explain the priority score</h3>${Object.entries(weights).map(([key,max])=>{const a=l.payload.assessment?.[key]||l.payload.suggestedAssessment?.[key]||{};return `<fieldset><legend>${e(labels[key])} · up to ${max}</legend><div class="form-grid"><label>Points<input type="number" name="${key}-points" min="0" max="${max}" value="${a.points||0}"></label>${field('Reason',key+'-reason',a.reason)}<label>Reviewed evidence<select name="${key}-claim"><option value="">No linked evidence</option>${claims.map(c=>`<option value="${c.id}" ${a.claimIds?.includes(c.id)?'selected':''}>${e(c.statement.slice(0,140))}</option>`).join('')}</select></label></div></fieldset>`;}).join('')}<button>Save lead & score</button><p class="error" role="alert"></p></form>`);}
 function addProject(){modal(`<h2>Add a public project announcement</h2><p>Start with one source-backed fact or announced plan. Unknown details stay empty. Further evidence can be imported for the same project.</p><form id="mi-project"><div class="form-grid">${field('Project name','name')}${field('Region / locality','region')}<label>State<select name="state">${options(states)}</select></label><label>Sector<select name="sector">${options(Object.keys(sectors))}</select></label><label>Current stage<select name="stage">${options(stages)}</select></label>${field('Organisation','organisation')}<label>Relationship<select name="relationship">${options(['owner','developer','EPC','engineering','construction','operator','funding'])}</select></label><label>Claim type<select name="kind">${options(['announced_plan','fact','forecast','unverified'])}</select></label>${field('Source URL (HTTPS)','url','','url')}${field('Source title','title')}${field('Publisher','publisher')}${field('Publication date','date','','date')}<label>Source type<select name="type">${options(['government','company','industry','other'])}</select></label></div><label>What does this source establish?<textarea name="statement" required></textarea></label><label>Exact supporting excerpt<textarea name="excerpt" required maxlength="1500"></textarea></label><label>Recommended consultant next step<textarea name="action" required></textarea></label><label class="check"><input type="checkbox" name="publicOnly" required>This is public evidence with no candidate information or private CRM records.</label><button>Save project for review</button><p class="error" role="alert"></p></form>`);}
 document.addEventListener('click',async event=>{const b=event.target.closest('[data-mi]');if(!b)return;event.preventDefault();const action=b.dataset.mi,id=b.dataset.id;b.disabled=true;try{
  if(action==='project')await showProject(id);else if(action==='lead')await showLead(id);else if(action==='add-project')addProject();else if(action==='claim'){const c=detail.claims.find(c=>c.id===id);modal(`<h2>Review claim</h2><p>${e(c.statement)}</p><form id="mi-claim" data-id="${id}"><label>Confidence<select name="confidence">${options(['Unverified','Confirmed','Corroborated','Estimated'])}</select></label><label>Review note<textarea name="note" required></textarea></label><label class="check"><input type="checkbox" name="confirmed" required>I checked the linked source and its support for this exact claim.</label><button>Save review</button><p class="error" role="alert"></p></form>`);}
  else if(action==='reconcile-job')modal(`<h2>Reconcile an uncertain submission</h2><p>Look up this exact request in the provider account. Enter its response ID to resume polling without sending another paid request. Do not guess an ID.</p><form id="mi-reconcile" data-id="${id}">${field('Provider response ID','responseId')}<button>Resume status checks</button><p class="error" role="alert"></p></form>`);else if(action==='report-form')modal(`<h2>Prepare a report</h2><form id="mi-report"><div class="form-grid">${field('Start date','start','','date')}${field('End date','end',new Date().toISOString().slice(0,10),'date')}</div><button>Create draft report</button><p class="error" role="alert"></p></form>`);
  else {if(action==='clear-filters'){search=sector=region=stage=minimum=windowFilter=developer='';}else if(['deep','verification'].includes(action)){await api('/intelligence/research',{method:'POST',body:{projectId:id,route:action}});toast('Research request saved. It will run only after spending is enabled.');}else if(action==='discovery'){await api('/intelligence/discovery',{method:'POST',body:{}});toast('Eight discovery jobs queued.');}else if(action==='retry-job'){await api('/intelligence/jobs/'+id+'/retry',{method:'POST',body:{}});toast('Job queued for another attempt.');}else if(action==='tick'){await api('/intelligence/tick',{method:'POST',body:{}});toast('Pending jobs processed. Check their status below.');}else if(action==='check-sources'){await api('/intelligence/sources/check',{method:'POST',body:{}});toast('Source checks completed; redirects and blocked links still need review.');}else if(action==='approve-report'||action==='validate-report'){await api(`/intelligence/reports/${id}/${action==='approve-report'?'approve':'validate'}`,{method:'POST',body:{}});toast(action==='approve-report'?'Report approved. Email settings still control distribution.':'Report refreshed; previous approval cleared.');}await load();await render();}
 }catch(err){toast(err.message);}finally{b.disabled=false;}});
 document.addEventListener('submit',async event=>{const f=event.target;if(!f.id.startsWith('mi-'))return;event.preventDefault();const d=Object.fromEntries(new FormData(f)),submit=f.querySelector('button[type="submit"],button:not([type])');if(submit)submit.disabled=true;try{
  if(f.id==='mi-filters'){({search,sector,region,stage,minimum,windowFilter,developer}=d);await render();return;}
  if(f.id==='mi-reconcile')await api('/intelligence/jobs/'+f.dataset.id+'/reconcile',{method:'POST',body:d});
 if(f.id.startsWith('mi-duplicate-'))await api('/intelligence/duplicates/'+f.dataset.id,{method:'POST',body:d});
 if(f.id==='mi-project'){const claim={statement:d.statement,kind:d.kind,sources:[{url:d.url,title:d.title,publisher:d.publisher,date:d.date||null,type:d.type,excerpt:d.excerpt}]};const result=await api('/intelligence/projects',{method:'POST',body:{publicOnly:!!d.publicOnly,project:{name:d.name,state:d.state,region:d.region,stage:d.stage,sectors:[d.sector],developer:d.relationship==='developer'?d.organisation:'',claims:[claim],organisations:d.organisation?[{name:d.organisation,relationship:d.relationship,claimIndex:0}]:[],action:d.action}}});toast(result.review?'Possible duplicate held for review.':'Project saved; review evidence before scoring.');}
  if(f.id==='mi-claim')await api('/intelligence/claims/'+f.dataset.id+'/review',{method:'POST',body:{...d,confirmed:!!d.confirmed}});
  if(f.id==='mi-lead'){const assessment={};for(const key of Object.keys(weights))assessment[key]={points:Number(d[key+'-points']),reason:d[key+'-reason'],claimIds:d[key+'-claim']?[d[key+'-claim']]:[]};await api('/intelligence/leads/'+f.dataset.id,{method:'PATCH',body:{...d,assessment,version:Number(f.dataset.version)}});}
  if(f.id==='mi-report')await api('/intelligence/reports',{method:'POST',body:d});
  if(f.id==='mi-settings'){const config=structuredClone(data.config);for(const k of ['monthlyCap','monthlyTarget','warningAt','criticalAt','shortlist','concurrency'])config[k]=Number(d[k]);config.enabled=d.enabled==='true';config.emailMode=d.emailMode;config.sourceDomains=d.sourceDomains.split(/\s+/).filter(Boolean);for(const key of Object.keys(config.routes))config.routes[key]={model:d[key+'-model'],effort:d[key+'-effort'],maxOutput:Number(d[key+'-maxOutput']),maxSearches:Number(d[key+'-maxSearches'])};await api('/intelligence/settings',{method:'PUT',body:{settings:config,version:data.configVersion}});}
  if(f.id==='mi-subscription')await api('/intelligence/subscriptions',{method:'POST',body:{email:d.email,active:d.active==='true',testOnly:d.testOnly==='true',sectors:[]}});
  document.querySelector('#modal')?.close();await load();await render();toast('Saved.');
 }catch(err){const target=f.querySelector('.error');if(target)target.textContent=err.message;else toast(err.message);}finally{if(submit)submit.disabled=false;}});
 return {routes,load,view};
}
